<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {get,request} from '../api/client'
type Row=Record<string,any>
const route=useRoute(),rows=ref<Row[]>([]),categories=ref<Row[]>([]),labels=ref<Row[]>([]),words=ref<Row[]>([]),types=ref<Row[]>([])
const busy=ref(false),error=ref(''),notice=ref(''),query=ref(''),selected=ref<Row|null>(null),editor=ref(false),form=ref<Row>({}),page=ref(1),total=ref(0)
const visible=computed(()=>rows.value)
const currentType=computed(()=>types.value.find(t=>t.code===form.value.contentType))
const keywordText=ref('')
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function load(){const result=await get('/api/v1/admin/articles/page',{page:page.value,size:20,q:query.value});rows.value=result.items;total.value=result.total}
async function catalogs(){[categories.value,labels.value,words.value,types.value]=await Promise.all([get('/api/v1/catalog/categories'),get('/api/v1/catalog/labels'),get('/api/v1/catalog/keywords'),get('/api/v1/content-types')])}
async function open(id?:string){await act(async()=>{
 selected.value=id?await get('/api/v1/admin/articles/'+id):null
 const value=selected.value,rel=value?.relationSnapshot?JSON.parse(value.relationSnapshot):{}
 form.value={title:'',summary:'',richText:'',originalText:'',sourceName:'',sourceUrl:'',contentType:'BASIC',pinned:false,urgent:false,pushEnabled:true,contentWeight:1,lifespan:'LONG',...value,categoryId:String(rel.categoryIds?.[0]||''),labelIds:(rel.labelIds||[]).map(String),keywordIds:(rel.keywordIds||[]).map(String),hotDays:value?.hotWeight||0,expectedVersion:value?.lockVersion||0}
 for(const field of ['effectiveFrom','effectiveTo']){const date=value?.[field]?new Date(value[field]):null;form.value[field]=date?new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16):''}
 form.value.longImageUrl=value?.richText?new DOMParser().parseFromString(value.richText,'text/html').querySelector('img')?.getAttribute('src')||'':''
 keywordText.value='';editor.value=true
})}
async function save(){await act(async()=>{
 const b:Row={...form.value,categoryIds:[form.value.categoryId],keywordNames:keywordText.value.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean)}
 for(const field of ['effectiveFrom','effectiveTo'])b[field]=form.value[field]?new Date(form.value[field]).toISOString():null
 await request(selected.value?'PUT':'POST',selected.value?'/api/v1/admin/articles/'+selected.value.id:'/api/v1/admin/articles',b)
 editor.value=false;notice.value=selected.value?'已保存修正；不会重复触发新资讯提醒。':'已保存并发布。';await catalogs();await load()
})}
async function state(row:Row,action:string){if(!confirm({OFFLINE:'下线后所有公开入口都不可访问，确认？',RESTORE:'恢复公开展示，确认？',END:'结束主动展示，历史详情仍可访问，确认？',DELETE:'删除此资讯，确认？'}[action]||'确认操作？'))return;await act(async()=>{await request('POST','/api/v1/admin/articles/'+row.id+'/state',{action,expectedVersion:row.lockVersion});await load()})}
const importOpen=ref(false),importTab=ref('file'),importText=ref(''),importFile=ref<File|null>(null),importKey=ref(crypto.randomUUID().replaceAll('-','')),result=ref<Row|null>(null)
function resetImport(){importText.value='';importFile.value=null;result.value=null;importKey.value=crypto.randomUUID().replaceAll('-','')}
function textChanged(){importKey.value=crypto.randomUUID().replaceAll('-','')}
function choose(e:Event){importFile.value=(e.target as HTMLInputElement).files?.[0]||null;result.value=null;importKey.value=crypto.randomUUID().replaceAll('-','')}
async function runImport(){await act(async()=>{
 let body:unknown,path:string
 if(importTab.value==='file'){if(!importFile.value)throw new Error('请选择JSON文件');const data=new FormData();data.append('file',importFile.value);body=data;path='/api/v1/admin/articles/import'}else{body={content:importText.value};path='/api/v1/admin/articles/import-text'}
 result.value=await request('POST',path,body,importKey.value);await load();await catalogs()
})}
async function copyFailures(){if(result.value)await navigator.clipboard.writeText(JSON.stringify(result.value.failList,null,2))}
function sample(){
 const category=categories.value[0],label=labels.value.find(l=>l.categoryId===category?.id)
 if(!category||!label){error.value='请先创建至少一个板块及其标签';return}
 const common={categoryName:category.name,labelNames:[label.name],keywordNames:['验收示例'],importance:1,hotDays:7,pushEnabled:false}
 const data=[{...common,contentType:'BASIC',title:'普通信息示例',levelOneContent:'原始材料',levelTwoContent:'<p>精炼正文</p>',levelThreeContent:'列表一句话'}, {...common,contentType:'NOTICE',title:'通知示例',levelTwoContent:'<p>通知正文</p>',effectiveFrom:'2026-01-01 00:00:00',effectiveTo:'2030-01-01 00:00:00'}, {...common,contentType:'GUIDE',title:'攻略示例',longImage:'https://example.invalid/replace-with-your-image.png',levelThreeContent:'请替换为可用长图链接'}]
 const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='yunji-import-example.json';a.click();URL.revokeObjectURL(url)
}
onMounted(()=>act(async()=>{await load();await catalogs();if(route.query.id)notice.value='请在列表中打开对应资讯编辑。'}))
</script>
<template><section><div class="title-row"><div><h1>资讯管理</h1><p class="muted">保存即发布；修正原文，大改新建后确认更替。</p></div><div class="actions"><button :disabled="busy" @click="importOpen=true">批量导入</button><button :disabled="busy" @click="open()">新建资讯</button></div></div><p class="error" role="alert">{{ error }}</p><p role="status">{{ notice }}</p><form class="panel actions" @submit.prevent="page=1;act(load)"><input v-model="query" placeholder="按标题搜索全部资讯" maxlength="100"/><button :disabled="busy">搜索</button><button type="button" class="quiet" :disabled="busy" @click="act(load)">刷新</button><span>共 {{ total }} 条</span></form><div class="panel"><table><thead><tr><th>标题</th><th>类型</th><th>状态</th><th>热点截止日</th><th>操作</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td>{{ row.title }}</td><td>{{ types.find(t=>t.code===row.contentType)?.name||row.contentType }}</td><td>{{ row.status==='OFFLINE'?'已下线':row.effectiveTo&&Date.parse(row.effectiveTo)<=Date.now()?'已结束':'已发布' }}</td><td>{{ row.hotUntil||'非热点' }}</td><td><button class="quiet" :disabled="busy" @click="open(row.id)">编辑</button><button class="quiet" :disabled="busy" @click="state(row,row.status==='OFFLINE'?'RESTORE':'OFFLINE')">{{ row.status==='OFFLINE'?'恢复':'下线' }}</button><button class="quiet" :disabled="busy" @click="state(row,'END')">结束</button><button class="danger" :disabled="busy" @click="state(row,'DELETE')">删除</button></td></tr></tbody></table><p v-if="!visible.length">暂无资讯</p><div class="actions"><button :disabled="page===1" @click="page--;act(load)">上一页</button><span>{{ page }}</span><button :disabled="page*20>=total" @click="page++;act(load)">下一页</button></div></div>
<div v-if="editor" class="overlay"><form class="dialog" @submit.prevent="save"><div class="title-row"><h2>{{ selected?'修正资讯':'新建资讯' }}</h2><button type="button" class="quiet" :disabled="busy" @click="editor=false">关闭</button></div><label>标题<input v-model="form.title" required maxlength="255"/></label><label>信息类型<select v-model="form.contentType" @change="form.lifespan=form.contentType==='NOTICE'?'SCHEDULED':'LONG'"><option v-for="t in types" :key="t.code" :value="t.code">{{ t.name }}</option></select></label><label>三级信息 · 列表一句话<textarea v-model="form.summary" :required="currentType?.requireSummary" maxlength="1000"/></label><label v-if="currentType?.renderer!=='LONG_IMAGE'">二级信息 · 正文<textarea v-model="form.richText" :required="currentType?.requireBody" rows="8" maxlength="100000"/></label><label v-if="currentType?.renderer==='LONG_IMAGE'">攻略长图URL<input v-model="form.longImageUrl" type="url" required maxlength="500"/></label><label v-if="currentType?.renderer!=='LONG_IMAGE'">一级信息 · 原文<textarea v-model="form.originalText" rows="4" maxlength="100000"/></label><label>原文链接<input v-model="form.sourceUrl" type="url" maxlength="500"/></label><label>来源名称<input v-model="form.sourceName" maxlength="150"/></label><div class="form-grid"><label>板块<select aria-label="板块" v-model="form.categoryId" required @change="form.labelIds=[]"><option value="">请选择</option><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>标签 · 至少一个<select aria-label="标签 · 至少一个" v-model="form.labelIds" multiple required><option v-for="l in labels.filter(l=>l.categoryId===form.categoryId)" :key="l.id" :value="l.id">{{ l.name }}</option></select></label><label>已有关键词<select v-model="form.keywordIds" multiple><option v-for="k in words" :key="k.id" :value="k.id">{{ k.name }}</option></select></label><label>新增关键词 · 逗号或换行分隔<textarea v-model="keywordText" placeholder="全局复用同名词，关键词合计至少一个"/></label><label>生效时间<input v-model="form.effectiveFrom" type="datetime-local" :required="currentType?.requireDates||form.lifespan==='SCHEDULED'"/></label><label>结束时间<input v-model="form.effectiveTo" type="datetime-local" :required="currentType?.requireDates"/></label><label>重要度<input v-model.number="form.contentWeight" type="number" min="1" max="5" required/></label><label>热点天数<input v-model.number="form.hotDays" type="number" min="0" max="30" required/></label><label>时限类型<select v-model="form.lifespan"><option value="LONG">长期</option><option value="SHORT">短期</option><option value="SCHEDULED">定时</option><option value="URGENT">紧急</option></select></label><label><input v-model="form.urgent" type="checkbox"/>紧急</label><label><input v-model="form.pinned" type="checkbox"/>置顶</label><label><input v-model="form.pushEnabled" type="checkbox"/>进入关注者盒子与提醒</label></div><p v-if="!form.hotDays" class="muted">非热点不会进入首页和板块列表；仍可经搜索等入口访问。</p><p class="error" role="alert">{{ error }}</p><button :disabled="busy">{{ selected?'保存修正':'保存并发布' }}</button></form></div>
<div v-if="importOpen" class="overlay"><div class="dialog"><div class="title-row"><h2>批量导入资讯</h2><button class="quiet" :disabled="busy" @click="importOpen=false">关闭</button></div><p>JSON数组，最多500条、5MiB；每条独立处理。默认热点0不会进入首页。失败条目可修改后作为新批导入。</p><div class="actions"><button class="quiet" :disabled="busy||!!result" @click="importTab='file'">上传文件</button><button class="quiet" :disabled="busy||!!result" @click="importTab='text'">粘贴JSON</button><button class="quiet" @click="sample">下载三类示例</button></div><input v-if="importTab==='file'" type="file" accept=".json,application/json" :disabled="busy||!!result" @change="choose"/><textarea v-else v-model="importText" rows="12" :disabled="busy||!!result" @input="textChanged"/><p class="error" role="alert">{{ error }}</p><div v-if="result" role="status"><h3>成功 {{ result.successCount }} · 失败 {{ result.failCount }} · 已处理 {{ result.processed }}/{{ result.total }}</h3><p>批次 {{ result.batchId }} · {{ result.status }}</p><p v-if="result.status!=='COMPLETED'">尚未全部完成；继续使用原请求恢复，已处理条目不会重复创建。</p><p v-if="result.createdKeywords.length">新建关键词：{{ result.createdKeywords.join('、') }}</p><p v-if="result.duplicatedKeywords?.length">复用关键词：{{ result.duplicatedKeywords.join('、') }}</p><table v-if="result.failList.length"><thead><tr><th>序号</th><th>标题</th><th>原因</th></tr></thead><tbody><tr v-for="f in result.failList" :key="f.index"><td>{{ f.index }}</td><td>{{ f.title }}</td><td>{{ f.reason }}</td></tr></tbody></table><button v-if="result.failList.length" class="quiet" @click="copyFailures">复制失败明细</button></div><div class="actions"><button :disabled="busy||result?.status==='COMPLETED'" @click="runImport">{{ busy?'正在处理…':result?'继续处理原批次':'开始导入' }}</button><button class="quiet" :disabled="busy" @click="resetImport">再导一次 · 清空</button></div></div></div>
</section></template>
